CREATE TABLE `us_counties` (
  `id` varchar(255) NOT NULL,
  `geoid` varchar(255) NOT NULL,
  `state_code` varchar(255) NOT NULL,
  `state_fips` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `admin_level` varchar(255) NOT NULL,
  `country_code` varchar(255) NOT NULL,
  `country_iso3` varchar(255) NOT NULL,
  `land_area_sqmi` varchar(255) NOT NULL,
  `water_area_sqmi` varchar(255) NOT NULL,
  `lat` varchar(255) NOT NULL,
  `lon` varchar(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

